mapper.select:
SELECT dot.id AS id, dot.cfg_output_id AS cfgOutputId, dot.next_level_id AS nextLevelId, dot.start_time AS startTime, dot.end_time AS endTime, dot.status AS status, dot.create_time AS createTime, dot.update_time AS updateTime, dot.create_user_name AS createUserName, dot.create_user_id AS createUserId, dot.update_user_name AS updateUserName, dot.update_user_id AS updateUserId, dot.version AS version, dot.is_deleted AS isDeleted, dot.task_type AS taskType, dot.error_count AS errorCount, dot.input_task_id AS inputTaskId, dot.exec_timeout AS execTimeout, dot.error_message AS errorMessage, dot.exec_system AS execSystem, dot.instance_id AS instanceId from dmp_output_task dot left join dmp_cfg_output dco on dot.cfg_output_id = dco.id where ${params.sqlMap.default} and dot.is_deleted = false
${params.permissionSql}
order by dot.update_time desc

SELECT CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN 'waitFinish' WHEN status = 'error' THEN 'error' WHEN status = 'finish' THEN 'finish' ELSE status END AS tabFlag, CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN '待完成' WHEN status = 'error' THEN '异常' WHEN status = 'finish' THEN '完成' ELSE status END AS tabFlagName, COUNT(*) AS count FROM dmp_output_task WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY tabFlag, tabFlagName
